{
  "implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError('Missing segments or budget')
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('Segments must be a non-empty list')
    required = {'name', 'importance', 'minimum', 'capacity'}
    for s in segments:
        if not isinstance(s, dict):
            raise ValueError('Each segment must be a dict')
        if not required.issubset(s.keys()):
            raise ValueError(f'Segment missing required keys: {required - s.keys()}')
        if not isinstance(s['name'], str) or not isinstance(s['importance'], (int, float)) or not isinstance(s['minimum'], int) or not isinstance(s['capacity'], int):
            raise ValueError('Invalid types in segment')
        if s['minimum'] < 0 or s['capacity'] < s['minimum']:
            raise ValueError('Invalid minimum or capacity')
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min:
        raise ValueError(f'Budget {budget} less than total minimum {total_min}')
    if budget > total_cap:
        raise ValueError(f'Budget {budget} greater than total capacity {total_cap}')
    allocations = {s['name']: s['minimum'] for s in segments}
    remaining = budget - total_min
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            if allocations[name] < s['capacity']:
                ratio = s['importance'] / (allocations[name] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            break
        name = segments[best_idx]['name']
        allocations[name] += 1
        remaining -= 1
    total = sum(allocations.values())
    names = [s['name'] for s in segments]
    return {
        'allocations': allocations,
        'names': names,
        'total': total
    }"
}
